<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>VoltSeal ROI Calculator | BESS Savings & Payback</title>
<meta name="description" content="Premium executive ROI calculator for VoltSeal Battery Energy Storage Systems. Instantly see savings, payback period, and 10-year profit." />
<style>
  *, *::before, *::after { box-sizing: border-box; }
  html, body { margin: 0; padding: 0; }
  body {
    font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    background: #F7F3EC;
    color: #1a2e26;
    -webkit-font-smoothing: antialiased;
  }
  .app {
    display: flex;
    flex-direction: column;
    min-height: 100vh;
    max-width: 1500px;
    margin: 0 auto;
  }
  @media (min-width: 1024px) { .app { flex-direction: row; } }

  /* Left panel */
  .left {
    width: 100%;
    padding: 2.5rem 2rem;
    display: flex;
    flex-direction: column;
    gap: 2.5rem;
    background: linear-gradient(165deg, #0E3B2E 0%, #184D3B 60%, #0E3B2E 100%);
    color: #fff;
  }
  @media (min-width: 1024px) { .left { width: 35%; padding: 3rem 2.5rem; } }
  .logo-wrap { display: flex; }
  .logo {
    width: 220px;
    max-width: 100%;
    height: auto;
    object-fit: contain;
    background: rgba(255, 255, 255, 0.95);
    border-radius: 18px;
    padding: 12px;
    box-shadow: 0 12px 30px -10px rgba(0, 0, 0, 0.4);
  }
  .title { font-size: 1.7rem; font-weight: 700; margin: 0 0 0.25rem; letter-spacing: -0.01em; }
  .subtitle { font-size: 0.9rem; color: rgba(220, 240, 230, 0.7); margin: 0; }

  .input-card {
    background: #fff;
    border-radius: 16px;
    padding: 1.75rem;
    box-shadow: 0 20px 50px -20px rgba(0, 0, 0, 0.45);
    display: flex;
    flex-direction: column;
    gap: 1.25rem;
  }
  .field label {
    display: block;
    font-size: 0.72rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: rgba(14, 59, 46, 0.7);
    margin-bottom: 0.5rem;
  }
  .input-row {
    display: flex;
    align-items: stretch;
    border: 1px solid rgba(14, 59, 46, 0.15);
    border-radius: 12px;
    overflow: hidden;
    background: rgba(247, 243, 236, 0.4);
    transition: border-color 0.15s, box-shadow 0.15s;
  }
  .input-row:focus-within { border-color: #0E3B2E; box-shadow: 0 0 0 3px rgba(14, 59, 46, 0.15); }
  .input-row input {
    flex: 1;
    border: 0;
    background: transparent;
    padding: 0.85rem 1rem;
    font-size: 1.1rem;
    font-weight: 600;
    color: #0E3B2E;
    outline: none;
    width: 100%;
    font-family: inherit;
  }
  .input-row input::placeholder { color: rgba(14, 59, 46, 0.3); }
  .input-row .unit {
    display: flex;
    align-items: center;
    padding: 0 1rem;
    background: rgba(14, 59, 46, 0.05);
    font-size: 0.85rem;
    font-weight: 600;
    color: rgba(14, 59, 46, 0.7);
  }
  .hint {
    margin-top: 0.5rem;
    font-size: 0.75rem;
    font-weight: 600;
    color: #b45309;
    opacity: 0;
    transform: translateY(-3px);
    transition: opacity 0.2s, transform 0.2s;
  }
  .hint.show { opacity: 1; transform: translateY(0); }

  .left-footer { margin-top: auto; display: none; }
  @media (min-width: 1024px) { .left-footer { display: block; } }
  .divider { height: 1px; background: rgba(255, 255, 255, 0.1); }
  .footer-note { margin-top: 1rem; font-size: 0.72rem; color: rgba(220, 240, 230, 0.5); }

  /* Right panel */
  .right {
    width: 100%;
    padding: 2.5rem 1.5rem;
    background: #F7F3EC;
  }
  @media (min-width: 1024px) { .right { width: 65%; padding: 3.5rem 3rem; } }
  .right-head {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    gap: 1rem;
    margin-bottom: 2rem;
    flex-wrap: wrap;
  }
  .eyebrow {
    font-size: 0.72rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.2em;
    color: rgba(14, 59, 46, 0.6);
    margin: 0;
  }
  .h2 { font-size: clamp(1.5rem, 2.2vw, 1.85rem); font-weight: 700; color: #0E3B2E; margin: 0.25rem 0 0; }
  .live { text-align: right; }
  .live small { font-size: 0.68rem; text-transform: uppercase; letter-spacing: 0.15em; color: rgba(14, 59, 46, 0.5); }
  .live p { margin: 0.15rem 0 0; font-size: 0.85rem; font-weight: 500; color: rgba(14, 59, 46, 0.8); }

  .grid { display: grid; gap: 1.25rem; grid-template-columns: 1fr; }
  .grid-3 { grid-template-columns: 1fr; }
  @media (min-width: 768px) { .grid-3 { grid-template-columns: repeat(3, 1fr); } }
  .row { margin-top: 1.25rem; }

  .kpi {
    position: relative;
    background: #fff;
    border-radius: 20px;
    padding: 1.6rem;
    box-shadow: 0 4px 20px -8px rgba(14, 59, 46, 0.18);
    border: 1px solid rgba(14, 59, 46, 0.05);
    transition: box-shadow 0.2s;
    overflow: visible;
  }
  .kpi:hover { box-shadow: 0 14px 35px -12px rgba(14, 59, 46, 0.28); }
  .kpi .accent-bar {
    position: absolute;
    left: 1.5rem;
    top: 0;
    transform: translateY(-50%);
    height: 4px;
    width: 48px;
    border-radius: 999px;
    background: linear-gradient(90deg, #0E3B2E, #184D3B);
  }
  .kpi-value-row { display: flex; align-items: baseline; gap: 0.5rem; white-space: nowrap; overflow: hidden; }
  .kpi-value {
    font-size: clamp(1.8rem, 3vw, 3rem);
    font-weight: 700;
    line-height: 1.1;
    color: #0E3B2E;
    white-space: nowrap;
  }
  .kpi-suffix { font-size: 0.9rem; font-weight: 600; color: rgba(14, 59, 46, 0.6); }
  .kpi-label { margin: 0.6rem 0 0; font-size: clamp(0.85rem, 1vw, 1rem); font-weight: 500; color: rgba(14, 59, 46, 0.7); }

  .kpi.dark {
    background: linear-gradient(135deg, #0E3B2E, #184D3B);
    color: #fff;
    box-shadow: 0 14px 35px -12px rgba(14, 59, 46, 0.5);
  }
  .kpi.dark .accent-bar { background: rgba(255, 255, 255, 0.85); }
  .kpi.dark .kpi-value { color: #fff; }
  .kpi.dark .kpi-label { color: rgba(255, 255, 255, 0.8); }
  .kpi.dark .years-suffix { font-size: 1.2rem; font-weight: 600; opacity: 0.8; margin-left: 0.35rem; }
  .kpi.dark .months { margin: 0.25rem 0 0; font-size: 0.9rem; color: rgba(255, 255, 255, 0.75); white-space: nowrap; }

  .assumption { margin-top: 2.5rem; font-size: 0.78rem; color: rgba(14, 59, 46, 0.6); }

  /* Remove number input arrows */
  input[type="number"]::-webkit-outer-spin-button,
  input[type="number"]::-webkit-inner-spin-button {
    -webkit-appearance: none;
    margin: 0;
  }
  input[type="number"] { -moz-appearance: textfield; }
</style>
</head>
<body>
<div class="app">
  <aside class="left">
    <div class="logo-wrap">
      <img class="logo" id="logo" alt="VoltSeal" src="data:image/png;base64," />
    </div>
    <div>
      <h1 class="title">BESS ROI Calculator</h1>
      <p class="subtitle">Estimate savings, payback, and long-term profitability.</p>
    </div>

    <div class="input-card">
      <div class="field">
        <label for="power">Power Requirement</label>
        <div class="input-row">
          <input id="power" type="number" min="0" inputmode="decimal" value="500" placeholder="500" />
          <span class="unit">kW</span>
        </div>
      </div>
      <div class="field">
        <label for="hours">DG Usage Per Day</label>
        <div class="input-row">
          <input id="hours" type="number" min="0" max="4" inputmode="decimal" value="2" placeholder="2" />
          <span class="unit">Hours</span>
        </div>
        <p class="hint" id="hours-hint">Max hours limit is 4.</p>
      </div>
      <div class="field">
        <label for="days">DG Operational Days</label>
        <div class="input-row">
          <input id="days" type="number" min="0" max="365" inputmode="decimal" value="250" placeholder="250" />
          <span class="unit">Days</span>
        </div>
        <p class="hint" id="days-hint">Max number of operating days is 365.</p>
      </div>
    </div>

    <div class="left-footer">
      <div class="divider"></div>
      <p class="footer-note">VoltSeal Battery Energy Storage Systems</p>
    </div>
  </aside>

  <section class="right">
    <header class="right-head">
      <div>
        <p class="eyebrow">Results Dashboard</p>
        <h2 class="h2">Your Projected ROI</h2>
      </div>
      <div class="live">
        <small>Live Calculation</small>
        <p>Updates instantly</p>
      </div>
    </header>

    <div class="grid grid-3">
      <div class="kpi">
        <span class="accent-bar"></span>
        <div class="kpi-value-row"><span class="kpi-value" id="annualSavings">—</span></div>
        <p class="kpi-label">Annual Savings</p>
      </div>
      <div class="kpi dark">
        <span class="accent-bar"></span>
        <div class="kpi-value-row">
          <span class="kpi-value" id="paybackYears">—</span>
          <span class="years-suffix">Years</span>
        </div>
        <p class="months"><span id="paybackMonths">—</span> Months</p>
        <p class="kpi-label">Payback Period</p>
      </div>
      <div class="kpi">
        <span class="accent-bar"></span>
        <div class="kpi-value-row"><span class="kpi-value" id="netProfit">—</span></div>
        <p class="kpi-label">Net Profit After 10 Years</p>
      </div>
    </div>

    <div class="grid grid-3 row">
      <div class="kpi">
        <div class="kpi-value-row">
          <span class="kpi-value" id="bess">—</span>
          <span class="kpi-suffix">kWh</span>
        </div>
        <p class="kpi-label">BESS Size</p>
      </div>
      <div class="kpi">
        <div class="kpi-value-row">
          <span class="kpi-value" id="energyDay">—</span>
          <span class="kpi-suffix">kWh/day</span>
        </div>
        <p class="kpi-label">Energy Saved Per Day</p>
      </div>
      <div class="kpi">
        <div class="kpi-value-row">
          <span class="kpi-value" id="annualEnergy">—</span>
          <span class="kpi-suffix">kWh/year</span>
        </div>
        <p class="kpi-label">Annual Energy Saved</p>
      </div>
    </div>

    <div class="grid row">
      <div class="kpi">
        <div class="kpi-value-row"><span class="kpi-value" id="capex">—</span></div>
        <p class="kpi-label">CAPEX</p>
      </div>
    </div>

    <p class="assumption">Assumption: Diesel generation cost considered at ₹32 per kWh.</p>
  </section>
</div>

<script>
(function() {
  const inputs = {
    power: { el: document.getElementById('power'), max: null, hint: null },
    hours: { el: document.getElementById('hours'), max: 4, hint: document.getElementById('hours-hint') },
    days: { el: document.getElementById('days'), max: 365, hint: document.getElementById('days-hint') },
  };

  const formatIndian = (num) => {
    if (!isFinite(num)) return '—';
    const rounded = Math.round(num);
    const sign = rounded < 0 ? '-' : '';
    const x = Math.abs(rounded).toString();
    let lastThree = x.substring(x.length - 3);
    const otherNumbers = x.substring(0, x.length - 3);
    if (otherNumbers !== '') lastThree = ',' + lastThree;
    const formatted = otherNumbers.replace(/\B(?=(\d{2})+(?!\d))/g, ',') + lastThree;
    return sign + '₹' + formatted;
  };

  const formatComma = (num) => isFinite(num) ? num.toLocaleString('en-IN', { maximumFractionDigits: 0 }) : '—';
  const formatDec = (num) => isFinite(num) ? num.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : '—';

  const hintTimers = {};
  function showHint(key) {
    const hint = inputs[key].hint;
    if (!hint) return;
    hint.classList.add('show');
    if (hintTimers[key]) clearTimeout(hintTimers[key]);
    hintTimers[key] = setTimeout(() => hint.classList.remove('show'), 2500);
  }

  function clampInput(key) {
    const el = inputs[key].el;
    const max = inputs[key].max;
    const raw = el.value;
    if (raw === '') {
      el.value = '';
      return '';
    }
    const num = parseFloat(raw);
    if (!isFinite(num)) return raw;
    if (max !== null && num > max) {
      el.value = max.toString();
      showHint(key);
      return max.toString();
    }
    el.value = num.toString();
    return num.toString();
  }

  function calculate() {
    const p = parseFloat(inputs.power.el.value) || 0;
    const h = parseFloat(inputs.hours.el.value) || 0;
    const d = parseFloat(inputs.days.el.value) || 0;

    const bess = (p * h) / 0.81;
    const energyDay = bess;
    const annualEnergy = energyDay * d;
    const annualSavings = annualEnergy * 25;
    const capex = bess * 19000;
    const payback = annualSavings > 0 ? capex / annualSavings : 0;
    const netProfit = annualSavings * 10 - capex;

    document.getElementById('annualSavings').textContent = formatIndian(annualSavings);
    document.getElementById('netProfit').textContent = formatIndian(netProfit);
    document.getElementById('bess').textContent = formatDec(bess);
    document.getElementById('energyDay').textContent = formatDec(energyDay);
    document.getElementById('annualEnergy').textContent = formatComma(annualEnergy);
    document.getElementById('capex').textContent = formatIndian(capex);
    document.getElementById('paybackYears').textContent = isFinite(payback) ? payback.toFixed(2) : '—';
    document.getElementById('paybackMonths').textContent = isFinite(payback) ? (payback * 12).toFixed(1) : '—';
  }

  Object.keys(inputs).forEach(key => {
    inputs[key].el.addEventListener('input', () => {
      clampInput(key);
      calculate();
    });
  });

  calculate();
})();
</script>
</body>
</html>
